main.script:

document.addEventListener("DOMContentLoaded", function () {
    // Scenario Presets Dictionary
    var presets = {
        mfg: {
            prompt: "Analyze high-frequency vibration telemetry on CNC Spindle #4, correlate with thermal sensor alerts, cross-reference ERP maintenance history, and trigger an automated SAP work order.",
            output: "STATUS: COMPLETED (Duration: 218ms)\n" +
                    "► [Step 1] Ingested 12,000 accelerometer samples from Spindle #4.\n" +
                    "► [Step 2] Detected 1.84kHz harmonic peak. Bearing fatigue probability: 98.4%.\n" +
                    "► [Step 3] Cross-referenced ERP BOM: SKF Explorer 6208 bearing required.\n" +
                    "► [Step 4] Deterministic Guardrail Check: PASSED. Generated Work Order #WO-89104 in SAP MES.\n" +
                    "► [Step 5] Autonomous Alert dispatched to Maintenance Supervisor via Telegram/SMS."
        },
        telecom: {
            prompt: "Stream MobiFone video batch #18204 for regulatory compliance, detect unauthorized watermarks, hate speech, and copyright infringement.",
            output: "STATUS: COMPLETED (Duration: 194ms)\n" +
                    "► [Step 1] Ingested 420 H.264 video keyframes at 60fps.\n" +
                    "► [Step 2] Multi-class frame classification: 0 toxic frames, 0 copyright infractions detected.\n" +
                    "► [Step 3] Audio transcription: 100% compliant with Vietnamese Media Broadcast regulations.\n" +
                    "► [Step 4] Digital Watermark Ledger stamped with SHA-256 hash #7c9f...a81.\n" +
                    "► [Step 5] Batch cleared for high-speed CDN broadcast."
        },
        energy: {
            prompt: "Monitor Substation 220kV gate CCTV, verify contractor credentials, validate PPE helmet, harness, and dielectric gloves before opening safety turnstile.",
            output: "STATUS: ACCESS GRANTED (Duration: 165ms)\n" +
                    "► [Step 1] FaceID detected contractor: Nguyen Van H. (ID #EVN-89412).\n" +
                    "► [Step 2] Electrical Safety Certificate Level 4 valid until 2027-12-31.\n" +
                    "► [Step 3] PPE Verification: Class-E Hardhat (OK), High-Vis Vest (OK), Dielectric Gloves (OK).\n" +
                    "► [Step 4] Perimeter Safety Turnstile #02 unlocked for 15 seconds.\n" +
                    "► [Step 5] Tamper-proof SCADA audit event logged to central command center."
        },
        supply: {
            prompt: "Evaluate warehouse safety stock for Lithium-Ion cells, simulate supply chain shipment lead time variance, and prepare auto-restock purchase orders.",
            output: "STATUS: RESTOCK ORDER GENERATED (Duration: 232ms)\n" +
                    "► [Step 1] Current stock: 4,200 units (Depletion rate: 680 units/day).\n" +
                    "► [Step 2] Port congestion delay projected: +4.2 days variance.\n" +
                    "► [Step 3] Reorder point breached: Initiated PO for 15,000 units from Tier-1 supplier.\n" +
                    "► [Step 4] Price matrix hedge applied: Savings of 4.8% vs spot market.\n" +
                    "► [Step 5] Routed to CFO authorization queue for one-click approval."
        }
    };

    // Console Preset Switcher
    var presetButtons = document.querySelectorAll(".mojo-prompt-btn");
    var promptInput = document.getElementById("mojo-console-prompt");
    var consoleOutput = document.getElementById("mojo-console-output");
    var runButton = document.getElementById("mojo-btn-run");
    var pipelineStatus = document.getElementById("mojo-pipeline-status");

    presetButtons.forEach(function (btn) {
        btn.addEventListener("click", function () {
            presetButtons.forEach(function (b) { b.classList.remove("active"); });
            btn.classList.add("active");
            var key = btn.getAttribute("data-preset");
            if (presets[key] && promptInput) {
                promptInput.value = presets[key].prompt;
            }
        });
    });

    // Run Agent Execution Animation
    if (runButton && promptInput && consoleOutput) {
        runButton.addEventListener("click", function () {
            runButton.disabled = true;
            if (pipelineStatus) pipelineStatus.textContent = "Executing Multi-Agent Swarm...";
            consoleOutput.textContent = "► [Stage 1] Parsing intent & policy boundaries...\n► [Stage 2] Accessing sovereign vector store...";

            var stepEls = [
                document.getElementById("mojo-step-1"),
                document.getElementById("mojo-step-2"),
                document.getElementById("mojo-step-3"),
                document.getElementById("mojo-step-4"),
                document.getElementById("mojo-step-5")
            ];

            stepEls.forEach(function (el) {
                if (el) {
                    el.className = "badge bg-info text-dark p-2";
                }
            });

            setTimeout(function () {
                var activeBtn = document.querySelector(".mojo-prompt-btn.active");
                var key = activeBtn ? activeBtn.getAttribute("data-preset") : "mfg";
                var res = presets[key] ? presets[key].output : presets.mfg.output;
                consoleOutput.textContent = res;
                if (pipelineStatus) pipelineStatus.textContent = "Complete // 0 Violations";
                runButton.disabled = false;
            }, 650);
        });
    }

    // Live Telemetry HUD Simulation
    setInterval(function () {
        var latencyEl = document.getElementById("hud-latency");
        var tokensEl = document.getElementById("hud-tokens");
        var accuracyEl = document.getElementById("hud-accuracy");
        var latencyBar = document.getElementById("hud-latency-bar");
        var tokensBar = document.getElementById("hud-tokens-bar");

        if (latencyEl) {
            var lat = 210 + Math.floor(Math.random() * 32);
            latencyEl.textContent = lat;
            if (latencyBar) latencyBar.style.width = Math.min(100, Math.floor((lat / 300) * 100)) + "%";
        }
        if (tokensEl) {
            var tok = 142 + Math.floor(Math.random() * 24);
            tokensEl.textContent = tok;
            if (tokensBar) tokensBar.style.width = Math.min(100, Math.floor((tok / 180) * 100)) + "%";
        }
        if (accuracyEl) {
            accuracyEl.textContent = (99.7 + Math.random() * 0.2).toFixed(1);
        }
    }, 1600);

    // Live Log Feed Append
    var streamBox = document.getElementById("hud-stream-logs");
    var logSamples = [
        "[FACTORY-CONVEYOR-02] Optical counting synced: 1,480 units/min. Defect rate: 0.00%.",
        "[TELECOM-FEEDBACK] Customer sentiment deflection: 94.2% satisfaction on billing agent route.",
        "[ENERGY-GRID] Feeder #14 power factor optimized to 0.98. Reactive loss minimized.",
        "[ORCHESTRATOR-SWARM] Passive quota accounting verified: 0 outbound Google scraping requests.",
        "[MULTIMODAL-VISION] Substation transformer thermography: Peak temp 48.2°C (Normal threshold: 75°C).",
        "[ERP-SYNC] SAP work order #WO-89105 status updated: Approved by Maintenance Lead."
    ];

    setInterval(function () {
        if (streamBox) {
            var now = new Date();
            var timeStr = now.toTimeString().split(" ")[0];
            var item = logSamples[Math.floor(Math.random() * logSamples.length)];
            var newRow = document.createElement("div");
            newRow.className = "text-muted mb-1";
            newRow.innerHTML = '<span class="text-secondary">[' + timeStr + ']</span> ' + item;
            streamBox.appendChild(newRow);
            if (streamBox.childNodes.length > 25) {
                streamBox.removeChild(streamBox.firstChild);
            }
            streamBox.scrollTop = streamBox.scrollHeight;
        }
    }, 2400);
});
